<?php $m=$summary; ?><?php include APP_PATH.'/views/partials/reports-tabs.php'; ?>
<div class="page-head"><div><div class="section-kicker">Shift reconciliation</div><h1>Close of day</h1><p class="lede">Review transactions, count the till, explain any variance, and create an immutable snapshot.</p></div><button class="btn btn-ghost no-print" type="button" onclick="window.print()">Print report</button></div>
<form method="get" action="<?= e(url('reports/z')) ?>" class="z-filter no-print"><label><span>Business date</span><input type="date" name="date" value="<?= e($date) ?>" max="<?= e(date('Y-m-d')) ?>"></label><?php if(Auth::isAdmin()): ?><label><span>Cashier</span><select name="user"><option value="0" <?= $userId===null?'selected':'' ?>>All staff — live overview</option><?php foreach($users as $user): ?><option value="<?= (int)$user['id'] ?>" <?= $userId===(int)$user['id']?'selected':'' ?>><?= e($user['name']) ?></option><?php endforeach; ?></select></label><?php endif; ?><button class="btn btn-primary btn-sm">Show shift</button></form>
<section class="z-summary"><article><small>Total sales</small><strong><?= money($m['total_sales']) ?></strong><span><?= number_format($m['sales_count']) ?> completed transactions</span></article><article><small>Expected cash</small><strong><?= money($m['expected_cash']) ?></strong><span><?= money($m['cash_sales']) ?> cash less <?= money($m['cash_refunds']) ?> cash refunds</span></article><article><small>Digital payments</small><strong><?= money($m['mpesa_sales']+$m['card_sales']+$m['bank_sales']) ?></strong><span>M-PESA, card, and bank</span></article><article><small>Exceptions</small><strong><?= number_format($m['voids_count']+$m['refunds_count']) ?></strong><span><?= number_format($m['voids_count']) ?> voids · <?= number_format($m['refunds_count']) ?> returns</span></article></section>
<div class="z-layout"><main><?php if($userId===null): ?><section class="inline-empty"><b>Select a cashier to close a shift</b><span>The all-staff view is live and cannot be closed as one till.</span></section><?php elseif($closed): ?><section class="card z-closed"><div class="z-closed-head"><span>✓</span><div><div class="section-kicker">Immutable snapshot #<?= (int)$closed['id'] ?></div><h2>Shift closed</h2><p><?= e($closed['user_name']) ?> · <?= e(date('d M Y',strtotime($closed['report_date']))) ?> · <?= e(date('h:i A',strtotime($closed['created_at']))) ?></p></div></div><div class="z-cash-result"><div><small>Expected cash</small><b><?= money($closed['expected_cash']) ?></b></div><div><small>Counted cash</small><b><?= money($closed['counted_cash']) ?></b></div><div class="<?= abs((float)$closed['variance'])>.009?'has-variance':'' ?>"><small>Variance</small><b><?= money($closed['variance']) ?></b></div></div><dl class="kv"><dt>Closed by</dt><dd><?= e($closed['closed_by_name']?:'Historical record') ?></dd><dt>Notes</dt><dd><?= e($closed['notes']?:'No notes') ?></dd></dl><div class="alert alert-info">This snapshot cannot be overwritten. Later sale adjustments do not change these recorded figures.</div></section><?php else: ?><form method="post" action="<?= e(url('reports/z/close')) ?>" class="card z-close-form"><?= csrf_field() ?><input type="hidden" name="date" value="<?= e($date) ?>"><input type="hidden" name="user_id" value="<?= (int)$userId ?>"><div class="section-kicker">Closing checklist</div><h2>Ready to close this shift?</h2><div class="z-checklist"><label><input type="checkbox" name="sales_reviewed" value="1" required><span><b>Sales reviewed</b><small><?= number_format($m['sales_count']) ?> completed · <?= number_format($m['voids_count']) ?> voided</small></span></label><label><input type="checkbox" name="offline_clear" value="1" required><span><b>Offline queue clear</b><small>Confirm this device has no unsynced sales.</small></span></label><label><input type="checkbox" name="payments_reviewed" value="1" required><span><b>Pending items reviewed</b><small><?= number_format($pendingPayments) ?> pending payments · <?= number_format($pendingReturns) ?> pending returns</small></span></label></div><div class="z-count-grid"><label class="field"><span>Expected cash</span><input value="<?= e(number_format($m['expected_cash'],2,'.','')) ?>" readonly></label><label class="field"><span>Counted cash</span><input type="number" name="counted_cash" min="0" step="0.01" required value="<?= e(number_format($m['expected_cash'],2,'.','')) ?>" data-counted-cash></label><div><small>Variance</small><strong data-cash-variance><?= money(0) ?></strong></div></div><label class="field"><span>Closing note</span><textarea name="notes" rows="3" maxlength="1000" placeholder="Required when there is a cash variance"></textarea></label><label class="dialog-confirm-check"><input type="checkbox" required><span>I confirm this count is final and understand the snapshot cannot be edited.</span></label><button class="btn btn-primary" type="submit">Close shift and save snapshot</button></form><?php endif; ?></main><aside class="card"><div class="section-kicker">Closed shifts</div><h2>Recent history</h2><?php if(!$history): ?><p class="muted">No closed shifts yet.</p><?php else: ?><div class="z-history"><?php foreach($history as $row): ?><a href="<?= e(url('reports/z?date='.$row['report_date'].'&user='.$row['user_id'])) ?>"><span><b><?= e(date('d M Y',strtotime($row['report_date']))) ?></b><small><?= e($row['user_name']?:'Former staff') ?> · <?= number_format($row['sales_count']) ?> sales</small></span><span><b><?= money($row['counted_cash']) ?></b><small class="<?= abs((float)$row['variance'])>.009?'text-danger':'' ?>">Variance <?= money($row['variance']) ?></small></span></a><?php endforeach; ?></div><?php endif; ?></aside></div>
<script>(function(){var input=document.querySelector('[data-counted-cash]'),out=document.querySelector('[data-cash-variance]');if(!input)return;var expected=<?= json_encode((float)$m['expected_cash']) ?>;function update(){var value=parseFloat(input.value)||0,diff=value-expected;out.textContent='KSh '+diff.toLocaleString('en-KE',{minimumFractionDigits:2,maximumFractionDigits:2});out.classList.toggle('text-danger',Math.abs(diff)>=.01);}input.addEventListener('input',update);update();})();</script>
